    27|/**
    28| * Fetch the initial page of the reels feed.
    29| * The backend returns { videos, next_cursor, total } with cursor pagination.
    30| */
    31|async function fetchFeedPage(limit: number): Promise<FeedVideo[]> {
    32|  const videos = await fetchVideoFeed(limit);
    33|  // De-duplicate by ID — never allow duplicate reel IDs in the feed.
    34|  const seen = new Set<string>();
    35|  return videos.filter((v) => {
    36|    if (seen.has(v.id)) return false;
    37|    seen.add(v.id);
    38|    return true;
    39|  });
