   128|      const errText = await presignRes.text().catch(() => `HTTP ${presignRes.status}`);
   129|      throw new Error(`Upload URL request failed: ${errText}`);
   130|    }
   131|
   132|    const presignData = await presignRes.json() as {
   133|      uploadUrl: string;
   134|      videoId: string;
   135|      thumbnailUrl?: string;
   136|    };
   137|    videoId = presignData.videoId;
   138|
