   140|    const uploadResponse = await fetch(selection.uri);
   141|    const blob = await uploadResponse.blob();
   142|
   143|    const uploadResult = await new Promise<void>((resolve, reject) => {
   144|      const xhr = new XMLHttpRequest();
   145|      xhr.open('PUT', presignData.uploadUrl);
   146|      xhr.setRequestHeader('Content-Type', 'video/mp4');
   147|
