    88| */
    89|type CacheEntry = { body: string; status: number; expiresAt: number };
    90|const FEED_CACHE = new Map<string, CacheEntry>();
    91|const FEED_CACHE_LOCKS = new Map<string, Promise<CacheEntry>>();
    92|const FEED_CACHE_TTL_MS = 30_000;
